def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    op_c = sum(1 for _, o in history if o == 'C')
    op_d = n - op_c

    last_me, last_op = history[-1]

    run_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_d += 1
        else:
            break

    r8 = sum(1 for _, o in history[-8:] if o == 'D')
    r16 = sum(1 for _, o in history[-16:] if o == 'D')

    if op_d * 2 > n:
        return 'D'
    if run_d >= 3:
        return 'D'
    if r8 >= 4:
        return 'D'
    if r16 >= 7:
        return 'D'

    if last_op == 'C':
        return 'C'

    if last_me == 'D':
        if op_d * 5 <= n * 2:
            return 'C'
        return 'D'

    if n >= 2 and history[-2][0] == 'D' and run_d == 1 and r8 <= 2:
        return 'C'

    return 'D'
